const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-1.187011, 29.135547]);
  const buffer = point.buffer(1000); // 1km buffer around point
  const augStart = '2024-08-07';
  const augEnd = '2024-08-17';
  const sepStart = '2024-09-24';
  const sepEnd = '2024-10-04';

  // Cloud mask function for Sentinel-2
  function maskS2Clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to process a date range
  async function getWaterCount(startDate, endDate, label) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(buffer)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
      .map(maskS2Clouds);

    const size = collection.size().getInfo();
    print(`${label} Images: ${size}`);

    if (size === 0) {
      // Try Landsat 9 as fallback for recent dates
      collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(buffer)
        .filterDate(startDate, endDate)
        .filter(ee.Filter.lt('CLOUD_COVER', 30));
      const landsatSize = collection.size().getInfo();
      print(`${label} Landsat Images: ${landsatSize}`);
      if (landsatSize === 0) return {count: null, label: label};

      // Use Landsat 9 with SR bands
      const composite = collection.median();
      // Landsat 9: Green = B3, SWIR1 = B6 for MNDWI
      const mndwi = composite.normalizedDifference(['SR_B3', 'SR_B6']);
      const water = mndwi.gt(0.1); // Threshold for water

      // Count water pixels
      const stats = water.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: buffer,
        scale: 30,
        maxPixels: 1e9
      });
      const count = stats.get('nd').getInfo();
      return {count: count, label: label};
    }

    // Sentinel-2 processing
    const composite = collection.median();
    // MNDWI: (Green - SWIR1) / (Green + SWIR1)
    // Sentinel-2: B3 = Green, B11 = SWIR1 (20m)
    const mndwi = composite.normalizedDifference(['B3', 'B11']);
    const water = mndwi.gt(0); // Simple threshold for water

    // Count water pixels
    const stats = water.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: buffer,
      scale: 20, // Match SWIR1 resolution
      maxPixels: 1e9
    });
    const count = stats.get('nd').getInfo();
    return {count: count, label: label};
  }

  // 2. Process both periods
  const augResult = await getWaterCount(augStart, augEnd, 'August');
  const sepResult = await getWaterCount(sepStart, sepEnd, 'September');

  // Check for empty collections
  if (augResult.count === null) {
    print("No data for August period.");
    print("<answer>C1</answer>");
    return;
  }
  if (sepResult.count === null) {
    print("No data for September period.");
    print("<answer>C1</answer>");
    return;
  }

  // Check for valid pixels
  if (augResult.count === 0) {
    print("August: 0 water pixels (all masked or dry).");
  }
  if (sepResult.count === 0) {
    print("September: 0 water pixels (all masked or dry).");
  }

  print(`August water pixels: ${augResult.count}`);
  print(`September water pixels: ${sepResult.count}`);

  // Check for calculation failures
  if (augResult.count === undefined || sepResult.count === undefined ||
      isNaN(augResult.count) || isNaN(sepResult.count)) {
    print("<answer>C3</answer>");
    return;
  }

  // 3. Compare and output final answer
  const increased = sepResult.count > augResult.count;
  print(`Water extent ${increased ? 'increased' : 'did not increase'}`);

  if (increased) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
